import { styleText } from 'node:util';
import logSymbols from 'log-symbols';
import { deploymentLabel } from './select-deployment.js';
import { pluralize, sectionHeader } from './ui.js';
export function needsFunctions(plan) {
    return plan.deployments.some((deployment) => deployment.emission !== undefined);
}
export function needsReportLines(plan) {
    return [
        sectionHeader('Runtime needs'),
        ...plan.deployments.flatMap((deployment) => ['', ...deploymentNeedsLines(deployment)]),
    ];
}
export function needsSummaryLines(plan) {
    return [
        sectionHeader('Runtime needs'),
        ...plan.deployments.flatMap((deployment) => deployment.emission === undefined ? [] : [summaryLine(deployment, deployment.emission)]),
    ];
}
function summaryLine(plan, emission) {
    const kinds = [
        { count: emission.drains.length, noun: 'effect drain' },
        { count: emission.heartbeat === undefined ? 0 : 1, noun: 'heartbeat' },
        { count: emission.startWatchers.length, noun: 'start watcher' },
    ].filter((kind) => kind.count > 0);
    const total = kinds.reduce((sum, kind) => sum + kind.count, 0);
    const breakdown = kinds.map((kind) => pluralize(kind.count, kind.noun)).join(', ');
    return `  ${planLabel(plan)} needs ${pluralize(total, 'Sanity Function')} (${breakdown})`;
}
function planLabel(plan) {
    return deploymentLabel({ name: plan.deploymentName, partition: plan.partition });
}
const DETAIL = '    → ';
const REASON = '      ';
function deploymentNeedsLines(plan) {
    const { emission } = plan;
    return [
        styleText('bold', `▸ ${planLabel(plan)}`),
        ...hostingLines(plan),
        ...(emission === undefined
            ? ['  no functions needed — the reactive session is already this deployment runtime']
            : [...drainLines(plan, emission), ...clockLines(plan, emission), ...watcherLines(emission)]),
        ...selfHostedLines(plan),
        ...warningLines(plan),
    ];
}
const HOSTING_NOTE = {
    function: '',
    durableFunction: 'no functions are emitted for these yet',
    selfHosted: 'nothing is emitted — your own process runs these',
};
const HOSTING_ORDER = ['function', 'durableFunction', 'selfHosted'];
function hostingLines(plan) {
    return [
        `  hosting: this deployment declares ${plan.runtimeKind}, and each level below inherits it`,
        ...kindLines('workflow', plan.hosting.workflows),
        ...kindLines('effect', plan.hosting.effects),
    ];
}
function kindLines(what, byKind) {
    return HOSTING_ORDER.flatMap((kind) => {
        const names = byKind[kind];
        if (names.length === 0)
            return [];
        const note = HOSTING_NOTE[kind];
        const suffix = note === '' ? '' : ` — ${note}`;
        return [`${DETAIL}${kind} ${what}(s): ${names.join(', ')}${suffix}`];
    });
}
const SELF_HOSTED_TASKS = [
    { key: 'startInstances', task: 'start instances of' },
    { key: 'tickDeadlines', task: 'tick the $now deadlines of' },
    { key: 'drainEffects', task: 'drain the effects' },
    { key: 'reevaluateParents', task: 're-evaluate, when a child settles,' },
];
function selfHostedLines(plan) {
    const tasks = SELF_HOSTED_TASKS.flatMap(({ key, task }) => {
        const names = plan.selfHosted[key];
        return names.length === 0 ? [] : [`${REASON}${task} ${names.join(', ')}`];
    });
    if (tasks.length === 0)
        return [];
    return ['  self-hosted: nothing below is emitted, so your own process must', ...tasks];
}
function drainLines(plan, emission) {
    const declared = plan.needs.drain.effectNames;
    if (declared.length === 0)
        return [];
    return [
        `  effects: ${declared.length} declared — ${declared.join(', ')}`,
        ...emission.drains.map((drain) => `${DETAIL}drain function ${drain.name} runs ${drain.effectNames.join(', ')}`),
    ];
}
function clockLines(plan, emission) {
    const { heartbeat } = emission;
    if (heartbeat === undefined)
        return [];
    const ticked = new Set(heartbeat.definitions);
    return [
        `  clock: ${heartbeatSentence(heartbeat)}`,
        ...timeSiteLines(plan.needs.heartbeat.timeSites.filter((site) => ticked.has(site.definition))),
        ...spawnSiteLines(plan.needs.heartbeat.spawnSites.filter((site) => ticked.has(site.definition))),
        `${DETAIL}scheduled function ${heartbeat.name} on ${heartbeat.schedule}`,
        ...(heartbeat.definitions.length === 0
            ? []
            : [`${REASON}ticks instances of ${heartbeat.definitions.join(', ')}`]),
        `${REASON}plan cadence: every minute on Enterprise, hourly on Growth, daily on Free` +
            ` (https://www.sanity.io/docs/functions/functions-introduction)`,
    ];
}
function heartbeatSentence(heartbeat) {
    const [first, ...rest] = heartbeat.reasons;
    const more = rest.map((reason) => `, and ${reason}`).join('');
    return `a scheduled function ${first} each minute, subject to plan cadence${more}`;
}
function timeSiteLines(sites) {
    return sites.map((site) => `${REASON}${site.definition} · ${site.stage ?? 'definition'} · ${site.address.kind} · ` +
        site.condition);
}
function spawnSiteLines(sites) {
    return sites.map((site) => `${REASON}${site.definition} · ${site.stage} · ${site.activity} · ${site.action} spawns ` +
        site.spawn.definition.name);
}
function watcherLines(emission) {
    if (emission.startWatchers.length === 0)
        return [];
    const started = [
        ...new Set(emission.startWatchers.flatMap((watcher) => watcher.definitions)),
    ].toSorted();
    return [
        `  autonomous starts: ${started.length} definition(s) — ${started.join(', ')}`,
        ...emission.startWatchers.flatMap((watcher) => [
            `${DETAIL}start watcher ${watcher.name} on ${watcher.projectId}.${watcher.dataset}` +
                ` — ${watcher.definitions.join(', ')}`,
            ...(watcher.updates.kind === 'noUpdate'
                ? [
                    `${REASON}starts a document when it is created; one that existed before this` +
                        ` watcher deployed starts only when you start it (sanity-workflows start)`,
                ]
                : []),
        ]),
    ];
}
function warningLines(plan) {
    return [
        ...plan.anyTypeSubjects.map((name) => `  ${logSymbols.warning} ${name} declares a subject with no types, so a write to any` +
            ` document type invokes its watcher — declare types unless that is intended`),
        ...plan.unnarrowedStartFilters.map((name) => `  ${logSymbols.warning} ${name} has a start filter that reads $now, another document,` +
            ` or the whole document, so every write to its subject types invokes its watcher, and a` +
            ` document that becomes eligible by time alone starts on its next write`),
        ...plan.subjectlessDefinitions.map((name) => `  ${logSymbols.warning} ${name} starts autonomously but declares no subject, so no` +
            ` document write can start it and it gets no watcher`),
    ];
}
